        public List<BaseModel> GetAllBettypes(int type)
        {
            List<BaseModel> bettypes = new List<BaseModel>();
            try
            {
                DataSet rs = _deleteBetsAccess.SelBettypes(type);
                DataTable dt = rs.Tables[0];
                switch (type)
                {
                    case Fanex.Tarus.Infrastructure.Constants.BetType.FirstHandicap:
                        DataRow newRow = dt.NewRow();
                        newRow["TypeID"] = 9;
                        dt.Rows.Add(newRow);
                        break;
                    default:
                        break;
                }

                string Name = string.Empty;
                BaseModel betType;
                foreach (DataRow dr in dt.Rows)
                {
                    betType = new BaseModel();
                    betType.Id = CastAide.AsInt32(dr["TypeID"]);
                    betType.Name = GetBettypeName(betType.Id, false);
                    bettypes.Add(betType);
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return bettypes;
        }

        public List<Result> CheckRefNo(string matchid, string fromRefno, string toRefno)
        {
            List<Result> listMessage = new List<Result>();
            Result checkResult = new Result();
            try
            {
                Hashtable outputParam = new Hashtable();
                DataSet dbResult = _specialDeleteAccess.CheckRefno(matchid, fromRefno, toRefno, ref outputParam);
                int errcode = CastAide.AsInt32(outputParam["errcode"]);
                string errmsg = CastAide.AsString(outputParam["errmsg"]);

                if (errcode > 0)
                {
                    checkResult.ErrorCode = errcode;
                    checkResult.ErrorMessage = errmsg;
                    listMessage.Add(checkResult);
                }
            }
            catch (Exception ex)
            {
                checkResult.ErrorCode = 101;
                checkResult.ErrorMessage = ex.Message;
                listMessage.Add(checkResult);
            }
            return listMessage;
        }

        public SpecialDeleteBetInfoList BettransSelSpecialDel(SpecialDeleteParam param)
        {
            SpecialDeleteBetInfoList specialDeleteDto = new SpecialDeleteBetInfoList();

            try
            {
                specialDeleteDto.Items = new List<SpecialDeleteByType>();
                specialDeleteDto.ErrorCode = 0;
                specialDeleteDto.ErrorMessage = string.Empty;

                param.UserName = AppSession.Username;
                DataSet dbResult = _deleteBetsAccess.BettransSelSpecialDel(param);
                if (dbResult != null && dbResult.Tables.Count > 0)
                {
                    var collections = GetDeleteBetConfig();
                    int index = 0;
                    foreach (DataTable dataTable in dbResult.Tables)
                    {
                        SpecialDeleteByType deleteByType = new SpecialDeleteByType();
                        List<BetTransactionInfomation> lstByType = new List<BetTransactionInfomation>();

                        Dictionary<string, object> element = collections[index];

                        string type = CastAide.AsString(element["Name"]);

                        AssignData(dataTable, type, ref lstByType);

                        deleteByType.Type = type;
                        deleteByType.TransactionInfo = new List<BetTransactionInfomation>();
                        deleteByType.TransactionInfo = lstByType;
                        deleteByType.IsAllowOptionDelete = (CastAide.AsString(element["IsAllowOptionDelete"]) == "1");
                        deleteByType.OptionType = CastAide.AsString(element["DeleteoOtionDefault"]);
                        specialDeleteDto.Items.Add(deleteByType);
                        index++;
                    }
                }
                else
                {
                    specialDeleteDto.ErrorCode = ErrorCode.NoInformation;
                    specialDeleteDto.ErrorMessage = Fanex.Tarus.VirtualSport.App_Resources.SpecialDelete.NoInfomationAvailable;
                }

                bool IsHasData = false;
                dbResult = _deleteBetsAccess.SelMatchInfo(CastAide.AsInt32(param.MatchId), CastAide.AsInt64(0));
                if (dbResult != null && dbResult.Tables.Count > 0)
                {
                    DataRow[] rows = dbResult.Tables[0].Select();
                    foreach (DataRow dataRow in rows)
                    {
                        IsHasData = true;
                        specialDeleteDto.AwayName = CacheRef.GetTeamName(dataRow["awayid"]);
                        specialDeleteDto.HomeName = CacheRef.GetTeamName(dataRow["homeid"]);
                        specialDeleteDto.EventDate = CastAide.AsDateTime(dataRow["eventdate"]).ToShortDateString();
                        specialDeleteDto.MatchCode = CastAide.AsString(dataRow["MatchCode"]);
                    }
                }

                if (!IsHasData)
                {
                    specialDeleteDto.ErrorCode = ErrorCode.NoMatch;
                    specialDeleteDto.ErrorMessage = Fanex.Tarus.VirtualSport.App_Resources.SpecialDelete.NoMatchInfo;
                }

            }
            catch (Exception ex)
            {
                specialDeleteDto.ErrorCode = ErrorCode.SystemError;
                specialDeleteDto.ErrorMessage = ex.Message;
                LogExtensions.ExceptionHandler(ex);
            }
            return specialDeleteDto;
        }

        #region DeleteSpecialTransaction

        public Result DeleteSpecialTransaction(SpecialDeleteParam deleteParam)
        {
            Result result = new Result(0, string.Empty);
            try
            {

                if (!PermissionService.HasHostPermission(Enumerations.Functions.SpecialDelete.SpecialDeleteVirtualSports))
                {
                    result.ErrorCode = ErrorCode.SystemError; //AlertMessage.GetMsg(errmsg, AlertMessage.MsgType.Error);
                    result.ErrorMessage = ResourceExtension.GetResourceValue(ResourceExtension.Resources.ErrorMsg, "_500");
                    return result;
                }
                Hashtable outputParam = new Hashtable();
                deleteParam.UserIp = HttpContext.Current.Request.UserHostAddress;
                deleteParam.UserId = AppSession.AccId;
                DataSet dbResult = _deleteBetsAccess.DeleteSpecialTransaction(deleteParam, ref outputParam);

                int errcode = CastAide.AsInt32(outputParam["errcode"]);
                string errmsg = CastAide.AsString(outputParam["errmsg"]);
                if (errcode > 0)
                {
                    result.ErrorCode = errcode;
                    result.ErrorMessage = errmsg;
                }
                else
                {
                    result.ErrorMessage += Fanex.Tarus.VirtualSport.App_Resources.SpecialDelete.DeleteBetTransSucceed;
                    //send private message to users
                    bool send = SendPrivateMsgToUsers(dbResult, CastAide.AsInt32(deleteParam.MatchId), deleteParam.SpecialDeleteMessage);
                    if (!send)
                    {
                        result.ErrorCode = ErrorCode.SystemError;
                        result.ErrorMessage += Fanex.Tarus.VirtualSport.App_Resources.SpecialDelete.ErrorWhenSendMailToUser;
                    }
                    result.ErrorMessage += SendEmailToCSD(errcode, errmsg, dbResult, VirtualSportsName);

                    result.ErrorMessage += SendEmailWhenDeleteBetToInternalGroup(errcode, errmsg, dbResult, VirtualSportsName, true); // for real currency
                    SendEmailWhenDeleteBetToInternalGroup(errcode, errmsg, dbResult, VirtualSportsName, false); // for test currency
                }
            }
            catch (Exception ex)
            {
                result.ErrorCode = ErrorCode.SystemError;
                result.ErrorMessage = ex.Message;
                LogExtensions.ExceptionHandler(ex);
            }
            return result;
        }

        #endregion DeleteSpecialTransaction
